text(''2d'');\n      chartInstanceRef.current = new ChartJS(ctx, config);\n\n      // Fire rendered event\n      if (onChartRendered) {\n        onChartRendered({\n          chartType: actualChartType,\n          dataPointCount: processData.chartData.length,\n          aggregateMethod: aggregateMethod,\n          totalValue: processData.values.reduce((a, b) => a + b, 0)\n        });\n      }\n\n    } catch (err) {\n      console.error(''[SimpleChart] Error rendering chart:'', err);\n      setError(`Failed to render chart: $' + CAST(N'' AS NVARCHAR(MAX)) + N'{err.message}`);\n    }\n\n    // Cleanup on unmount\n    return () => {\n      if (chartInstanceRef.current) {\n        chartInstanceRef.current.destroy();\n        chartInstanceRef.current = null;\n      }\n    };\n  }, [processData, actualChartType, title, height, colors, styles, showLegend, legendPosition, legendFontSize, showDataLabels, enableExport, ChartJS]);\n\n  // Download chart as image\n  React.useEffect(() => {\n    if (enableExport && chartInstanceRef.current && canvasRef.current) {\n      // Add a simple export button overlay\n      const exportHandler = () => {\n        const url = canvasRef.current.toDataURL(''image/png'');\n        const link = document.createElement(''a'');\n        link.download = `$' + CAST(N'' AS NVARCHAR(MAX)) + N'{title || ''chart''}.png`;\n        link.href = url;\n        link.click();\n      };\n      \n      // Store handler for cleanup\n      window.SimpleChartExport = exportHandler;\n    }\n    \n    return () => {\n      delete window.SimpleChartExport;\n    };\n  }, [enableExport, title]);\n\n  // Error state\n  if (error) {\n    return (\n      <div style={{ \n        display: ''flex'', \n        flexDirection: ''column'',\n        justifyContent: ''center'', \n        alignItems: ''center'', \n        height: height,\n        color: errorColor,\n        padding: ''20px''\n      }}>\n        <div>Error rendering chart</div>\n        <div style={{ fontSize: ''12px'', marginTop: ''8px'', color: subtleColor }}>{error}</div>\n      </div>\n    );\n  }\n\n  // Empty state\n  if (!data || data.length === 0 || processData.isEmpty) {\n    return (\n      <div style={{ \n        display: ''flex'', \n        justifyContent: ''center'', \n        alignItems: ''center'', \n        height: height,\n        color: subtleColor,\n        backgroundColor: surfaceAltColor,\n        borderRadius: ''4px''\n      }}>\n        No data available to display\n      </div>\n    );\n  }\n\n  // Render chart container with canvas\n  return (\n    <div style={{ width: ''100%'', position: ''relative'', overflow: ''hidden'' }}>\n      {enableExport && (\n        <div style={{ display: ''flex'', justifyContent: ''flex-end'', marginBottom: ''8px'' }}>\n          <button\n            onClick={() => window.SimpleChartExport && window.SimpleChartExport()}\n            style={{\n              padding: ''4px 8px'',\n              fontSize: ''12px'',\n              backgroundColor: surfaceColor,\n              border: `1px solid $' + CAST(N'' AS NVARCHAR(MAX)) + N'{borderColor}`,\n              borderRadius: ''4px'',\n              cursor: ''pointer'',\n              display: ''flex'',\n              alignItems: ''center'',\n              gap: ''4px''\n            }}\n            title=\"Download as PNG\"\n          >\n            ⬇ Export\n          </button>\n        </div>\n      )}\n      <div style={{ width: ''100%'', height: `$' + CAST(N'' AS NVARCHAR(MAX)) + N'{height}px` }}>\n        <canvas ref={canvasRef} />\n      </div>\n    </div>\n  );\n}","exampleUsage":"<!-- Ranking Example: Top products by revenue (explicit sort by value) -->\n<SimpleChart\n  entityName=\"Invoice Line Items\"\n  data={invoiceItems}\n  groupBy=\"ProductCategory\"\n  valueField=\"TotalAmount\"\n  aggregateMethod=\"sum\"\n  chartType=\"bar\"\n  title=\"Top 10 Products by Revenue\"\n  limit={10}\n  sortBy=\"value\"  // Explicit sort by revenue for ranking\n  sortOrder=\"desc\"  // Hi