  currency: ''USD'',\n            minimumFractionDigits: 2,\n            maximumFractionDigits: 2\n          }).format(num);\n        }\n        return num.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n      }\n    }\n    \n    // Text fields - truncate if needed\n    if (typeof value === ''string'' && value.length > maxTextLength) {\n      return (\n        <span title={value}>\n          {value.substring(0, maxTextLength)}...\n        </span>\n      );\n    }\n    \n    return value;\n  };\n  \n  // Get fields to display\n  const getDisplayFields = () => {\n    if (fields && fields.length > 0) {\n      return fields;\n    }\n    \n    // Auto-select fields if not specified\n    if (!record) return [];\n    \n    return Object.keys(record).filter(key => \n      !key.startsWith(''__mj'') && \n      key !== ''ID'' &&\n      typeof record[key] !== ''object''\n    );\n  };\n  \n  // Get field info from entity\n  const getFieldInfo = (fieldName) => {\n    if (!entityInfo || !entityInfo.Fields) return null;\n    return entityInfo.Fields.find(f => f.Name === fieldName);\n  };\n  \n  // Handle field click\n  const handleFieldClick = (fieldName, value) => {\n    if (onFieldClicked) {\n      const fieldInfo = getFieldInfo(fieldName);\n      onFieldClicked({ \n        fieldName, \n        value, \n        fieldType: fieldInfo?.Type,\n        record \n      });\n    }\n  };\n  \n  \n  // Render field based on layout\n  const renderField = (fieldName) => {\n    const fieldInfo = getFieldInfo(fieldName);\n    const value = record[fieldName];\n    const formattedValue = formatValue(value, fieldInfo);\n    \n    if (!showEmptyFields && !formattedValue) return null;\n    \n    const isHighlighted = highlightFields.includes(fieldName);\n    const label = fieldInfo?.DisplayName || fieldName;\n    \n    const fieldStyle = {\n      cursor: onFieldClicked ? ''pointer'' : ''default''\n    };\n    \n    const highlightStyle = isHighlighted ? {\n      backgroundColor: warningSurfaceColor,\n      padding: ''4px 8px'',\n      borderRadius: ''4px'',\n      border: `1px solid $' + CAST(N'' AS NVARCHAR(MAX)) + N'{warningBorderColor}`\n    } : {};\n    \n    if (layout === ''list'' \n        || layout === ''card'') {\n      return (\n        <div \n          key={fieldName}\n          style={{ \n            marginBottom: ''12px'',\n            ...highlightStyle\n          }}\n          onClick={() => handleFieldClick(fieldName, value)}\n        >\n          {showLabels && (\n            <div style={{ \n              fontWeight: 500, \n              color: labelColor, \n              fontSize: ''12px'',\n              marginBottom: ''4px'',\n              textTransform: ''uppercase''\n            }}>\n              {label}\n            </div>\n          )}\n          <div style={{ \n            fontSize: ''14px'', \n            color: textColor,\n            ...fieldStyle\n          }}>\n            {formattedValue || ''-''}\n          </div>\n        </div>\n      );\n    }\n    \n    if (layout === ''table'') {\n      return (\n        <tr \n          key={fieldName}\n          style={highlightStyle}\n          onClick={() => handleFieldClick(fieldName, value)}\n        >\n          {showLabels && (\n            <td style={{ \n              fontWeight: 500, \n              color: labelColor, \n              fontSize: ''14px'',\n              padding: ''8px'',\n              width: labelWidth,\n              verticalAlign: ''top''\n            }}>\n              {label}\n            </td>\n          )}\n          <td style={{ \n            fontSize: ''14px'', \n            color: textColor,\n            padding: ''8px'',\n            ...fieldStyle\n          }}>\n            {formattedValue || ''-''}\n          </td>\n        </tr>\n      );\n    }\n    \n    if (layout === ''inline'') {\n      return (\n        <span \n          key={fieldName}\n          style={{ \n            marginRight: ''20px'',\n            display: ''inline-block'',\n            ...highlightStyle\n          }}\n          onClick={() => handleFieldClick(fieldName, value)}\n        >\n          {showLabels && (\n            <span style={{ \n              fontWeight: 500, \n              color: labelColor, \n              fontSize: ''12px'',\n              marginRight: ''4px''\n            }}>\n              {label}:\n            </span>\n          )}\n          <span style={{ \n            fontSize: ''14px'', \n            color: textColor,\n            ...fieldStyle\n          }}>\n            {formattedValue || ''-''}\n          </span>\n        </span>\n      );\n    }\n    \n    return null;\n  };\n  \n  // No record provided\n  if (!record) {\n    return (\n      <div style={{ \n        padding: ''20px'', \n        textAlign: ''center'', \n        color: mutedColor \n      }}>\n        No record to display\n      </div>\n    );\n  }\n  \n  const displayFields = getDisplayFields();\n  \n  // Render based on layout\n  if (layout === ''card'') {\n    return (\n      <div style={{\n        border: `1px solid $' + CAST(N'' AS NVARCHAR(MAX)) + N'{borderColor}`,\n        borderRadius: ''8px'',\n        padding: ''16px'',\n        backgroundColor: surfaceColor,\n        boxShadow: `0 2px 4px $' + CAST(N'' AS NVARCHAR(MAX)) + N'{shadowColor}`\n      }}>\n        {displayFields.map(renderField)}\n        {allowOpenRecord && WrappedOpenRecordButton && (\n          <div style={{ marginTop: ''16px'', paddingTop: ''16px'', borderTop: `1px solid $' + CAST(N'' AS NVARCHAR(MAX)) + N'{borderLightColor}` }}>\n            <WrappedOpenRecordButton\n              record={record}\n              entityName={entityName}\n              variant=\"primary\"\n              size=\"medium\"\n              utilities={utilities}\n              styles={styles}\n              components={components}\n              callbacks={callbacks}\n              savedUserSettings={savedUserSettings}\n              onSaveUserSettings={onSaveUserSettings}\n            />\n          </div>\n        )}\n      </div>\n    );\n  }\n  \n  if (layout === ''table'') {\n    return (\n      <div>\n        <table style={{\n          width: ''100%'',\n          borderCollapse: ''collapse''\n        }}>\n          <tbody>\n            {displayFields.map(renderField)}\n          </tbody>\n        </table>\n        {allowOpenRecord && WrappedOpenRecordButton && (\n          <div style={{ marginTop: ''12px'' }}>\n            <WrappedOpenRecordButton\n              record={record}\n              entityName={entityName}\n              variant=\"default\"\n              size=\"medium\"\n              utilities={utilities}\n              styles={styles}\n              components={components}\n              callbacks={callbacks}\n              savedUserSettings={savedUserSettings}\n              onSaveUserSettings={onSaveUserSettings}\n            />\n          </div>\n        )}\n      </div>\n    );\n  }\n  \n  if (layout === ''inline'') {\n    return (\n      <div style={{\n        padding: ''8px'',\n        lineHeight: ''1.8''\n      }}>\n        {displayFields.map(renderField)}\n        {allowOpenRecord && WrappedOpenRecordButton && (\n          <span style={{ marginLeft: ''20px'', display: ''inline-block'' }}>\n            <WrappedOpenRecordButton\n              record={record}\n              entityName={entityName}\n              variant=\"link\"\n              size=\"small\"\n              utilities={utilities}\n              styles={styles}\n              components={components}\n              callbacks={callbacks}\n              savedUserSettings={savedUserSettings}\n              onSaveUserSettings={onSaveUserSettings}\n            />\n          </span>\n        )}\n      </div>\n    );\n  }\n  \n  // Default list layout\n  return (\n    <div style={{ padding: ''8px'' }}>\n      {displayFields.map(renderField)}\n      {shouldShowOpenButton && (\n        <div style={{ marginTop: ''12px'' }}>\n          <OpenRecordButton\n            record={record}\n            entityName={entityName}\n            variant=\"default\"\n            size=\"medium\"\n            utilities={utilities}\n            styles={styles}\n            components={components}\n            callbacks={callbacks}\n            savedUserSettings={savedUserSettings}\n            onSaveUserSettings={onSaveUserSettings}\n          />\n        </div>\n      )}\n    </div>\n  );\n}","exampleUsage":"<SingleRecordView\n  record={selectedDeal}\n  entityName=\"Deals\"\n  fields={[''DealName'', ''Stage'', ''Amount'', ''CloseDate'', ''OwnerID'']}\n  layout=\"card\"\n  highlightFields={[''Amount'', ''Stage'']}\n  allowOpenRecord={true}\n  onOpenRecord={(eventData) => {\n    // Example: Cancel if deal is in certain stage\n    if (selectedDeal.Stage === ''Lost'') {\n      eventData.cancel = true;\n      alert(''Cannot open lost deals'');\n    }\n  }}\n/>"}'
