  @Title = @Title_fed2e205,
  @Description = @Description_fed2e205,
  @Type = @Type_fed2e205,
  @Status = @Status_fed2e205,
  @DeveloperName = @DeveloperName_fed2e205,
  @DeveloperName_Clear = 1,
  @DeveloperEmail = @DeveloperEmail_fed2e205,
  @DeveloperEmail_Clear = 1,
  @DeveloperOrganization = @DeveloperOrganization_fed2e205,
  @DeveloperOrganization_Clear = 1,
  @SourceRegistryID = @SourceRegistryID_fed2e205,
  @SourceRegistryID_Clear = 1,
